INSERT IGNORE INTO products (id, category_id, name, brand, description, price, image_path) VALUES
    (1, 1, 'Vợt Cầu Lông Yonex Arcsaber 1 Clear Chính Hãng', 'Yonex', 'Giới thiệu sản phẩm\nYonex Arcsaber 1 Clear chính hãng là mẫu vợt thuộc dòng Arcsaber nổi tiếng của Yonex, được thiết kế hướng đến khả năng kiểm soát cầu chính xác và cảm giác đánh ổn định. Đây là lựa chọn phù hợp cho người mới chơi, học sinh, sinh viên hoặc người chơi phong trào muốn sở hữu một cây vợt dễ sử dụng với mức đầu tư hợp lý.\nThuộc phân khúc phổ thông của dòng Arcsaber, sản phẩm mang đến sự cân bằng giữa tốc độ, độ linh hoạt và khả năng điều cầu. Bên cạnh đó, thiết kế hiện đại cùng công nghệ khung vợt đặc trưng của Yonex giúp người chơi tự tin hơn trong cả tấn công lẫn phòng thủ.\nTham khảo thêm các mẫu vợt cầu lông Yonex tại Vợt Cầu Lông Shop.\nThông số kỹ thuật\nThương hiệu:...', 559000, 'p-01-vot-cau-long-yonex-arcsaber-1-clear-chinh.webp'),
    (2, 1, 'Vợt Cầu Lông Yonex Arcsaber 1 Ability Chính Hãng', 'Yonex', 'Giới thiệu sản phẩm\nYonex Arcsaber 1 Ability chính hãng là mẫu vợt thuộc dòng Arcsaber nổi tiếng của Yonex, được thiết kế dành cho người chơi phong trào và những ai đang tìm kiếm một cây vợt dễ kiểm soát, trợ lực tốt và có độ ổn định cao trong từng pha cầu.\nSở hữu công nghệ đặc trưng của dòng Arcsaber, cây vợt giúp giữ cầu trên mặt vợt lâu hơn, từ đó nâng cao khả năng điều hướng và kiểm soát điểm rơi chính xác. Đây là lựa chọn đáng cân nhắc trong phân khúc tầm trung của dòng vợt cầu lông Yonex , phù hợp cho cả đánh đơn lẫn đánh đôi.\nThông số kỹ thuật\nThương hiệu: Yonex\nDòng vợt: Arcsaber\nMã sản phẩm: Arcsaber 1 Ability\nĐộ cứng: Trung bình\nĐiểm cân bằng: Cân bằng\nTrọng lượng: 4U (khoảng...', 559000, 'p-02-vot-cau-long-yonex-arcsaber-1-ability-chin.webp'),
    (3, 1, 'Vợt Cầu Lông Yonex Astrox 100 Game Chính Hãng', 'Yonex', 'Giới thiệu sản phẩm\nYonex Astrox 100 Game chính hãng là mẫu vợt tầm trung nổi bật thuộc dòng Astrox nổi tiếng của Yonex, hướng đến lối chơi tấn công mạnh mẽ nhưng vẫn đảm bảo khả năng kiểm soát và xoay chuyển linh hoạt. Sản phẩm được phát triển dựa trên nền tảng của phiên bản Astrox 100ZZ cao cấp, mang lại trải nghiệm đập cầu uy lực cùng cảm giác cầm chắc tay hơn cho người chơi phong trào và bán chuyên.\nMẫu vợt này sở hữu thiết kế hiện đại, phối màu nổi bật cùng nhiều công nghệ đặc trưng của Yonex giúp tăng độ ổn định khi vung vợt. Nếu bạn đang tìm kiếm một cây vợt cầu lông Yonex thiên công nhưng vẫn dễ làm quen thì Astrox 100 Game là lựa chọn rất đáng cân nhắc.\nThông số kỹ thuật\nThương...', 2079000, 'p-03-vot-cau-long-yonex-astrox-100-game-chinh-h.webp'),
    (4, 1, 'Vợt cầu lông Halbertec 9000 Power 2026 Chính Hãng', 'Li-Ning', 'Li-Ning Halbertec 9000 Power 2026 là mẫu vợt cao cấp dành cho người chơi yêu thích lối đánh thiên công hiện đại: smash mạnh, xử lý cầu nhanh và vẫn duy trì độ chính xác ở các pha phản tạt. Cây vợt sở hữu trọng lượng 4U, điểm cân bằng khoảng 302 mm thiên nặng đầu, kết hợp thân vợt mỏng 6.6 mm để tạo lực tốt mà không làm cảm giác vung trở nên quá ì.\nThuộc dòng Halbertec nổi tiếng của Li-Ning, Halbertec 9000 Power tập trung vào khả năng truyền lực, giảm rung và giữ ổn định khi đánh cầu ở tốc độ cao. Chất liệu T1100 kết hợp Ultra-Modulus Graphite giúp vợt có kết cấu chắc chắn, chịu được mức căng đến 30 lbs và đáp ứng tốt nhu cầu của người chơi trung bình khá, bán chuyên hoặc vận động...', 3640000, 'p-05-vot-cau-long-halbertec-9000-power-2026-chi.webp'),
    (5, 1, 'Vợt Cầu Lông Lining Axforce 80 Gen II (AYPW049-4V) Chính Hãng', 'Li-Ning', 'Vợt Cầu Lông Lining Axforce 80 Gen II (AYPW049-4V) Chính Hãng chính hãng thương hiệu Li-Ning. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 3379000, 'p-06-vot-cau-long-lining-axforce-80-gen-ii-aypw.webp'),
    (6, 1, 'Vợt Cầu Lông Lining Bladex 800 Speed Chính Hãng', 'Li-Ning', 'Vợt Cầu Lông Lining Bladex 800 Speed Chính Hãng chính hãng thương hiệu Li-Ning. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 3220000, 'p-07-vot-cau-long-lining-bladex-800-speed-chinh.webp'),
    (7, 1, 'Vợt cầu lông Victor Drivex 12 Chính Hãng', 'Victor', 'Giới thiệu sản phẩm\nVictor Drivex 12 chính hãng là mẫu vợt nổi bật trong dòng Drivex, hướng đến người chơi yêu thích sự kiểm soát và ổn định trong từng pha cầu. Với thiết kế cân bằng cùng công nghệ hiện đại, cây vợt giúp người chơi dễ dàng điều tiết nhịp độ trận đấu.\nNằm trong phân khúc cao cấp của vợt cầu lông Victor , Victor Drivex 12 chính hãng mang lại trải nghiệm đánh chắc tay, phù hợp cho cả thi đấu và tập luyện.\nThông số kỹ thuật\nTrọng lượng: 3U (85–89g) / 4U (80–84g)\nĐiểm cân bằng: Cân bằng\nĐộ cứng: Trung bình – cứng\nChất liệu khung: High Resilience Modulus Graphite + Nano Resin\nChất liệu trục: Ultra High Modulus Graphite\nChiều dài: 675 mm\nChu vi cán: G5, G6\nMàu sắc: Đen phối...', 3800000, 'p-08-vot-cau-long-victor-drivex-12-chinh-hang.webp'),
    (8, 1, 'Vợt cầu lông Victor Auraspeed Panther C', 'Victor', 'Victor Auraspeed Panther C là mẫu vợt cầu lông thuộc dòng Auraspeed, hướng đến lối chơi công thủ toàn diện nhưng ưu tiên tốc độ, phản tạt và khả năng làm chủ nhịp cầu. Vợt sở hữu phối màu đen kết hợp vàng gold nổi bật, phù hợp với người chơi yêu thích thiết kế mạnh mẽ và cá tính.\nCây vợt sử dụng khung High Resilience Modulus Graphite kết hợp NANO AEROGEL và HARD CORED TECHNOLOGY, đi cùng thân vợt 6.8 mm tích hợp PYROFIL. Cấu hình này hỗ trợ vợt duy trì cảm giác chắc chắn, phản hồi nhanh và ổn định khi xử lý các pha drive, chụp lưới, điều cầu hoặc phản công liên tục.\nThông số kỹ thuật Victor Auraspeed Panther C\nThông tin\nChi tiết\nThương hiệu\nVictor\nMã sản phẩm\nARS-PANTHER C\nDòng sản...', 2099000, 'p-09-vot-cau-long-victor-auraspeed-panther-c.webp'),
    (9, 1, 'Vợt Cầu Lông Mizuno Jpx Reserve Edition Mb', 'Mizuno', 'Vợt cầu lông Mizuno JPX Reserve Edition MB là siêu phẩm mới nhất dành cho những tay vợt yêu thích tốc độ và sức mạnh bùng nổ. Với thiết kế đầu nặng, thân cứng cùng hàng loạt công nghệ đột phá từ Mizuno, cây vợt này mang đến trải nghiệm tấn công sắc bén, kiểm soát chính xác và độ bền vượt trội. Nếu bạn đang tìm kiếm một cây vợt cầu lông Mizuno JPX Reserve Edition MB chất lượng cao cấp, đây chính là lựa chọn không thể bỏ qua trong năm 2025.\nTổng quan về siêu phẩm Mizuno JPX Reserve Edition MB\nVợt Cầu Lông Mizuno Jpx Reserve Edition MB thuộc dòng JPX Reserve cao cấp của Mizuno, được thiết kế dành riêng cho lối chơi tấn công mạnh mẽ. Phiên bản MB (Midnight Blue) sở hữu màu sắc sang trọng...', 1790000, 'p-10-vot-cau-long-mizuno-jpx-reserve-edition-mb.webp'),
    (10, 1, 'Vợt cầu lông Mizuno Fortius 50 Swift', 'Mizuno', 'Mizuno Fortius 50 Swift là mẫu vợt cầu lông thuộc dòng Fortius, hướng đến người chơi yêu thích lối đánh tấn công nhưng vẫn cần tốc độ xoay trở linh hoạt. Vợt có trọng lượng 5U nhẹ, thân cứng và điểm cân bằng nặng đầu, tạo cấu hình phù hợp cho các pha đập cầu, phông cầu chủ động và phản công nhanh.\nPhiên bản 73MTB45002 sở hữu phối màu Pewter Gray, đen và Green Oasis, tương ứng xám phối đen cùng điểm nhấn xanh chuối. Vợt sử dụng cấu tạo Japan HMG T46, tích hợp nhiều công nghệ hỗ trợ tăng độ ổn định khung, giảm rung và cải thiện tốc độ phản hồi khi chạm cầu.\nThông số kỹ thuật Mizuno Fortius 50 Swift\nThông tin\nChi tiết\nThương hiệu\nMizuno\nTên sản phẩm\nMizuno Fortius 50 Swift\nMã sản...', 1890000, 'p-11-vot-cau-long-mizuno-fortius-50-swift.webp'),
    (11, 1, 'Vợt Cầu Lông Kumpoo Pc-99 Pro', 'Kumpoo', 'Vợt Cầu Lông Shop luôn cập nhật những mẫu vợt cầu lông mới nhất cho các lông thủ có nhiều lựa chọn. Hôm nay là một mẫu vợt chính hãng từ Kumpoo – một hãng vợt nội địa Trung, có giá thành rẻ và chất lượng tốt. Đó chính là Vợt cầu lông Kumpoo PC-99 Pro\nThông số kĩ thuật\n– Thương hiệu: Kumpoo\n– Màu sắc: Hồng\n– Chất liệu khung vợt: Carbon Fiber\n– Chất liệu thân vợt: Carbon Fiber\n– Độ cân bằng: 290 ± 5mm\n– Độ cứng: Trung bình\n– Chiều dài vợt: 675 mm\n– Hệ thống 76 lỗ trên mặt vợt\n– Trọng lượng: 4U\n– Chu vi cán vợt: G6\n– Mức căng lưới: 22 – 28LBS ~', 550000, 'p-12-vot-cau-long-kumpoo-pc-99-pro.webp'),
    (12, 2, 'Giày Cầu Lông Yonex Bnce (bshbnce) Chính Hãng', 'Yonex', 'Giày Cầu Lông Yonex Bnce (bshbnce) Chính Hãng chính hãng thương hiệu Yonex. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 950000, 'p-13-giay-cau-long-yonex-bnce-bshbnce-chinh-han.webp'),
    (13, 2, 'Giày Cầu Lông Yonex Graphite Throttle (gt1lexz-naturl) Chính Hãng', 'Yonex', 'Giới thiệu Giày Cầu Lông Yonex Grpht Thrttl\nGiày cầu lông Yonex Grpht Thrttl  là sản phẩm mang công nghệ “Graphite Throttle” hoàn toàn mới, được Yonex công bố ra mắt toàn cầu vào tháng 10 năm 2025. Mẫu giày này đóng vai trò là một “concept shoe” (giày thử nghiệm) để giới thiệu một nền tảng công nghệ sẽ được tích hợp vào tất cả các dòng giày Yonex trong tương lai. Grpht Thrttl được thiết kế để hoạt động như một “ống ga”, cho phép người chơi điều tiết và giải phóng năng lượng một cách hiệu quả nhất, mang lại độ nảy, sự ổn định và cảm giác thoải mái chưa từng có.\nCông nghệ Đột Phá trên Yonex Graphite Throttle\nHiệu suất đỉnh cao của  Giày cầu lông Yonex Grpht Thrttl  đến từ sự kết hợp của hai...', 3650000, 'p-15-giay-cau-long-yonex-graphite-throttle-gt1l.webp'),
    (14, 2, 'Giày Cầu Lông Mizuno Wave Fang 2 71GA231351', 'Mizuno', 'Giày Cầu Lông Mizuno Wave Fang 2 71GA231351 chính hãng thương hiệu Mizuno. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 1824350, 'p-16-giay-cau-long-mizuno-wave-fang-2-71ga23135.webp'),
    (15, 2, 'Giày Cầu Lông Mizuno Wave Claw Neo 3 71GA247332', 'Mizuno', 'Giày Cầu Lông Mizuno Wave Claw Neo 3 71GA247332 chính hãng thương hiệu Mizuno. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 1760000, 'p-17-giay-cau-long-mizuno-wave-claw-neo-3-71ga2.webp'),
    (16, 2, 'Giày Cầu Lông Mizuno Wave Fang 2 71GA231345', 'Mizuno', 'Giày Cầu Lông Mizuno Wave Fang 2 71GA231345 chính hãng thương hiệu Mizuno. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 1824350, 'p-18-giay-cau-long-mizuno-wave-fang-2-71ga23134.webp'),
    (17, 2, 'Giày Cầu Lông Victor P9200CXLTD', 'Victor', 'Giới thiệu sản phẩm\nGiày cầu lông Victor P9200cXLTD là phiên bản cao cấp thuộc dòng P9200 nổi tiếng của Victor, được thiết kế dành cho người chơi yêu cầu độ ổn định và cảm giác êm ái khi di chuyển. Sản phẩm nổi bật với khả năng giảm chấn tốt, hỗ trợ di chuyển linh hoạt và bảo vệ bàn chân hiệu quả trong các pha cầu cường độ cao.\nGiày cầu lông Victor P9200cXLTD thuộc phân khúc trung cao cấp, tích hợp nhiều công nghệ đệm và chống trượt hiện đại. Đây là lựa chọn phù hợp cho người chơi muốn nâng cao hiệu suất thi đấu và giảm áp lực lên cổ chân.\nBạn có thể tham khảo thêm các dòng giày cầu lông hoặc khám phá bộ sưu tập giày cầu lông Mizuno chính hãng.\nThông số kỹ thuật\nThương hiệu: Victor\nMã sản...', 4400000, 'p-19-giay-cau-long-victor-p9200cxltd.webp'),
    (18, 2, 'Giày Cầu Lông Victor P9200 Cx Chính Hãng', 'Victor', 'Giày Cầu Lông Victor P9200 Cx Chính Hãng chính hãng thương hiệu Victor. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 2990000, 'p-20-giay-cau-long-victor-p9200-cx-chinh-hang.webp'),
    (19, 3, 'Áo cầu lông Lining 9002B', 'Li-Ning', 'Áo cầu lông Lining 9002B chính hãng thương hiệu Li-Ning. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 180000, 'p-21-ao-cau-long-lining-9002b.webp'),
    (20, 3, 'Áo Cầu Lông Lining ATSU493-2V', 'Li-Ning', 'Áo Cầu Lông Lining ATSU493-2V chính hãng thương hiệu Li-Ning. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 300000, 'p-22-ao-cau-long-lining-atsu493-2v.webp'),
    (21, 3, 'Váy Cầu Lông Yonex SKL-S092-3571-MYMAS26-S (ladies Skorts) Chính Hãng', 'Yonex', 'Váy Cầu Lông Yonex SKL-S092-3571-MYMAS26-S (ladies Skorts) Chính Hãng chính hãng thương hiệu Yonex. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 379000, 'p-23-vay-cau-long-yonex-skl-s092-3571-mymas26-s.webp'),
