    (23, 3, 'Váy Cầu Lông Lining 035 Trắng', 'Li-Ning', 'Váy Cầu Lông Lining 035 Trắng chính hãng thương hiệu Li-Ning. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 160000, 'p-25-vay-cau-long-lining-035-trang.webp'),
    (24, 3, 'Áo Yonex Essential 5 RM-S092-3577-ESST5-S', 'Yonex', 'Áo Yonex Essential 5 RM-S092-3577-ESST5-S là mẫu áo thể thao nam thuộc dòng Essential 5 của Yonex. Sản phẩm có thiết kế cổ tròn gọn gàng, phù hợp cho người chơi cầu lông cần một mẫu áo dễ mặc trong các buổi tập, thi đấu phong trào hoặc hoạt động thể thao hằng ngày.\nPhiên bản màu Winter Green mang sắc xanh trầm, tạo vẻ ngoài hiện đại và dễ phối với quần short đen, trắng hoặc xanh navy. Áo có các size từ S đến 2XL, đáp ứng nhiều nhu cầu lựa chọn theo vóc dáng và phong cách mặc.\nThông tin áo Yonex Essentia 5 RM-S092-3577-ESST5-S\nThông tin\nChi tiết\nThương hiệu\nYonex\nDòng sản phẩm\nYonex Essential 5\nMã sản phẩm\nRM-S092-3577-ESST5-S\nKiểu dáng\nÁo thun cổ tròn nam\nMàu sắc\nWinter Green\nKích thước\nS,...', 269000, 'p-27-ao-yonex-essential-5-rm-s092-3577-esst5-s.webp'),
    (25, 3, 'Áo Cầu Lông Yonex RM-J035-3513-RW4-S', 'Yonex', 'Áo Cầu Lông Yonex RM-J035-3513-RW4-S chính hãng thương hiệu Yonex. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 129000, 'p-28-ao-cau-long-yonex-rm-j035-3513-rw4-s.webp'),
    (26, 4, 'Balo cầu lông Yonex VA BA02612V Chính Hãng', 'Yonex', 'Balo cầu lông Yonex VA BA02612V là mẫu Expert Backpack thuộc bộ sưu tập Viktor Axelsen của Yonex. Sản phẩm được thiết kế cho người chơi cần mang vợt, giày, ống cầu, quần áo tập và đồ cá nhân trong một form balo gọn gàng, dễ di chuyển đến sân.\nBalo có phối màu xanh đậm đặc trưng của VA Collection, kết hợp chi tiết đồ họa và điểm nhấn vàng. Với kích thước 31,5 × 21 × 48 cm, Yonex VA BA02612V phù hợp cho người chơi tập luyện thường xuyên, đi đánh đôi, đi CLB hoặc mang đồ thi đấu trong ngày.\nBalo cầu lông Yonex VA BA02612V là gì?\nBalo cầu lông Yonex VA BA02612V là balo chuyên dụng thuộc dòng Expert Backpack của Yonex, được phát triển trong bộ sưu tập mang dấu ấn của Viktor Axelsen. Balo có các...', 2850000, 'p-30-balo-cau-long-yonex-va-ba02612v-chinh-hang.webp'),
    (27, 4, 'Túi Đeo Chéo Yonex BAG-Q014-226-1839 Chính Hãng', 'Yonex', 'Túi Đeo Chéo Yonex BAG-Q014-226-1839 Chính Hãng chính hãng thương hiệu Yonex. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 359000, 'p-31-tui-deo-cheo-yonex-bag-q014-226-1839-chinh.webp'),
    (28, 4, 'Balo Cầu Lông Victor BR5080 ZSW Chính Hãng', 'Victor', 'Balo Cầu Lông Victor BR5080 ZSW là mẫu balo hai quai thuộc VICTOR x ZSW Collection 2.0 , phù hợp cho người chơi cần mang vợt, giày, bình nước và phụ kiện đến sân trong một thiết kế gọn gàng. Balo có kích thước 32 × 20 × 48 cm , sử dụng chất liệu PU Leather kết hợp Polyester , nổi bật với phối màu trắng và tím pastel.\nĐiểm đáng chú ý của Victor BR5080 ZSW là hệ thống ngăn chứa được phân tách rõ ràng: ngăn đựng vợt riêng, ngăn giày độc lập, túi trước để phụ kiện và hai túi bên tiện dụng. Đây là lựa chọn phù hợp cho người chơi muốn dùng balo thay vì mang túi vợt cỡ lớn khi đi tập hoặc đánh cầu hằng ngày.\nThông số kỹ thuật Balo Cầu Lông Victor BR5080 ZSW\nHạng mục\nThông tin\nTên sản phẩm\nBalo Cầu...', 1400000, 'p-32-balo-cau-long-victor-br5080-zsw-chinh-hang.webp'),
    (29, 4, 'Túi Vợt Cầu Lông Victor BR5681 HYQ Chính Hãng', 'Victor', 'Túi Vợt Cầu Lông Victor BR5681 HYQ là mẫu túi vợt dáng chữ nhật thuộc VICTOR x Huang Ya Qiong Collection 2.0 , phù hợp cho người chơi cần mang vợt, giày, phụ kiện và đồ dùng đi sân trong một chiếc túi gọn gàng. Sản phẩm nổi bật với ngăn vợt riêng có lớp cách nhiệt , ngăn giày độc lập và túi trước đựng phụ kiện.\nVictor BR5681 HYQ có kích thước 75 × 20 × 33 cm , sử dụng chất liệu PU Leather kết hợp Polyester và phiên bản màu Bright White – trắng sáng . Đây là lựa chọn đáng cân nhắc cho người chơi tập luyện thường xuyên hoặc cần một mẫu túi vợt có khả năng sắp xếp dụng cụ rõ ràng hơn balo thông thường.\nThông số kỹ thuật Túi Vợt Cầu Lông Victor BR5681 HYQ\nHạng mục\nThông tin\nTên sản phẩm\nTúi Vợt...', 1699000, 'p-33-tui-vot-cau-long-victor-br5681-hyq-chinh-h.webp'),
    (30, 4, 'Balo Cầu Lông Lining Absu459-1 Chính Hãng', 'Li-Ning', 'Balo Cầu Lông Lining Absu459-1 Chính Hãng chính hãng thương hiệu Li-Ning. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 630000, 'p-34-balo-cau-long-lining-absu459-1-chinh-hang.webp'),
    (31, 4, 'Túi Cầu Lông Lining Abjt059-2 Chính Hãng', 'Li-Ning', 'Các sản phẩm túi cầu lông từ thương hiệu Lining luôn nổi bật với những thiết kế độc đáo và cuốn hút, kết hợp với chất lượng vật liệu cao cấp và độ hoàn thiện tuyệt vời. Túi Cầu Lông Lining ABJT059-1 Chính Hãng không ngoại lệ, với phong cách phối màu đơn giản và kiểu dáng khỏe khoắn. Sản phẩm này thích hợp cho mọi giới tính và độ tuổi, mang lại sự thời trang và tiện lợi cho người sử dụng.\nThông số kĩ thuật\nMã sản phẩm: Lining ABJT059-1 Chính Hãng\nThương hiệu: Lining\nKích thước: 76 – 24 – 28', 990000, 'p-35-tui-cau-long-lining-abjt059-2-chinh-hang.webp'),
    (32, 4, 'Balo Lining Abss275-5 Chính Hãng', 'Li-Ning', 'Balo Lining Abss275-5 Chính Hãng chính hãng thương hiệu Li-Ning. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 720000, 'p-36-balo-lining-abss275-5-chinh-hang.webp'),
    (33, 5, 'Cuốn Vs 002', 'VS', 'Cuốn Vs 002 chính hãng thương hiệu VS. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 15000, 'p-37-cuon-vs-002.webp'),
    (34, 5, 'Cuốn Cán Vải Apavi Ag-110', 'Apavi', 'Tìm hiểu Cuốn Cán Vải Apavi Ag-110 | Vợt Cầu Lông chi tiết, thông tin hữu ích và cập nhật mới nhất tại Vợt Cầu Lông Shop.', 20000, 'p-38-cuon-can-vai-apavi-ag-110.webp'),
    (35, 5, 'Cuốn Vải Apavi Ag-204r (10m)', 'Apavi', 'Cuốn cán vải Apavi AG-204R dạng cuộn dài 10m, thấm hút mồ hôi tốt và êm tay khi đánh cầu lâu. Chính hãng thương hiệu Apavi.', 250000, 'p-39-cuon-vai-apavi-ag-204r-10m.webp'),
    (36, 5, 'Vớ Yonex SSR-2964-S Chính Hãng White', 'Yonex', 'Vớ Yonex SSR-2964-S White là mẫu vớ thể thao thuộc dòng Tru 3D của Yonex, thiết kế dành cho người thường xuyên vận động, tập luyện và thi đấu cầu lông. Sản phẩm có gam màu trắng dễ phối cùng giày cầu lông, trang phục thể thao và phù hợp sử dụng hằng ngày.\nForm vớ ôm gọn bàn chân, giúp cảm giác mang ổn định hơn khi di chuyển, bật nhảy hoặc đổi hướng liên tục trên sân. Đây là lựa chọn phù hợp cho người chơi cần một đôi vớ Yonex chính hãng có thiết kế đơn giản, dễ dùng và hỗ trợ tốt cho các buổi tập.\nThông tin sản phẩm vớ Yonex SSR-2964-S\nThông tin\nChi tiết\nThương hiệu\nYonex\nMã sản phẩm\nSSR-2964-S\nDòng sản phẩm\nTru 3D Socks\nMàu sắc\nWhite – Trắng\nKích thước tham khảo\n22–25 cm\nPhù hợp sử...', 104000, 'p-41-vo-yonex-ssr-2964-s-chinh-hang-white.webp'),
    (37, 5, 'Vớ Yonex SSR-1961-S Chính Hãng', 'Yonex', 'Vớ Yonex SSR-1961-S là mẫu vớ thể thao thuộc dòng Tru 3D của Yonex, phù hợp cho người chơi cầu lông cần cảm giác mang gọn chân và ổn định khi vận động. Sản phẩm có form ôm theo bàn chân, hỗ trợ hạn chế cảm giác xô lệch khi di chuyển nhanh, bật nhảy hoặc đổi hướng liên tục trên sân.\nVới hai lựa chọn màu Jet Black và White, Yonex SSR-1961-S dễ phối cùng giày cầu lông và trang phục thể thao. Đây là phụ kiện phù hợp để sử dụng trong những buổi tập thường xuyên, thi đấu hoặc các hoạt động vận động hằng ngày.\nThông tin vớ Yonex SSR-1961-S\nThông tin\nChi tiết\nThương hiệu\nYonex\nMã sản phẩm\nSSR-1961-S\nDòng sản phẩm\nTru 3D Socks\nKích thước tham khảo\n25–28 cm\nMàu sắc\nJet Black, White\nPhù hợp sử...', 99000, 'p-42-vo-yonex-ssr-1961-s-chinh-hang.webp'),
    (38, 5, 'Vớ Kaiwin Diamond', 'Kaiwin', 'Giới thiệu sản phẩm\nVớ Kaiwin Diamond là phụ kiện thể thao thiết yếu dành cho người chơi Pickleball và cầu lông, giúp tối ưu cảm giác di chuyển và bảo vệ bàn chân khi vận động. Sản phẩm thuộc nhóm phụ kiện Pickleball được thiết kế chú trọng vào sự thoải mái và độ bền.\nVới kiểu dáng thể thao cùng họa tiết Diamond nổi bật, vớ không chỉ hỗ trợ thi đấu hiệu quả mà còn mang lại phong cách năng động cho người sử dụng.\nThông số kỹ thuật\nThương hiệu: Kaiwin\nLoại: Vớ thể thao / vớ Pickleball\nChất liệu: Cotton kết hợp sợi co giãn (Spandex/Polyester)\nSize: Freesize / nhiều size\nĐộ dày: Trung bình, hỗ trợ đệm chân\nĐộ co giãn: Tốt, ôm chân\nMàu sắc: Nhiều màu, họa tiết Diamond\nTính năng: Thấm hút mồ hôi,...', 48000, 'p-43-vo-kaiwin-diamond.webp'),
    (39, 5, 'Mũ Yonex ND Nhật', 'Yonex', 'Mũ Yonex ND Nhật chính hãng thương hiệu Yonex. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 250000, 'p-44-mu-yonex-nd-nhat.webp'),
    (40, 5, 'Chip Victor Intelligence VI-01', 'Victor', 'Chip Victor Intelligence VI-01 là mô-đun cảm biến AI dành cho người chơi cầu lông muốn theo dõi dữ liệu luyện tập trực quan hơn. Sản phẩm được tích hợp ở phần nắp cuối cán vợt Victor tương thích, ghi nhận chuyển động khi vung vợt và truyền dữ liệu đến ứng dụng để người chơi nhìn lại thói quen đánh cầu của mình.\nĐây không phải là một cây vợt cầu lông, mà là phụ kiện công nghệ hỗ trợ phân tích quá trình tập luyện. Chip Victor Intelligence VI-01 phù hợp với người chơi muốn theo dõi tốc độ vung vợt, lực đập, kiểu kỹ thuật thường dùng và xu hướng lối chơi để điều chỉnh bài tập có cơ sở hơn.\nChip Victor Intelligence VI-01 là gì?\nChip Victor Intelligence VI-01 là cảm biến thông minh được đặt tại...', 2650000, 'p-45-chip-victor-intelligence-vi-01.webp'),
    (41, 5, 'Móc Khóa Lining Hình Túi Vợt P-AQAW099-1', 'Li-Ning', 'Móc Khóa Lining Hình Túi Vợt P-AQAW099-1 chính hãng thương hiệu Li-Ning. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 120000, 'p-46-moc-khoa-lining-hinh-tui-vot-p-aqaw099-1.webp'),
    (42, 5, 'Cuốn Yonex Ac102ex (3 Wraps) Chính Hãng', 'Yonex', 'Tìm hiểu Cuốn Yonex Ac102ex (3 Wraps) Chính Hãng | Vợt Cầu Lông chi tiết, thông tin hữu ích và cập nhật mới nhất tại Vợt Cầu Lông Shop.', 120000, 'p-40-cuon-yonex-ac102ex-3-wraps-chinh-hang.webp'),
    (43, 4, 'Túi cầu lông Yonex VA BA02631V Chính Hãng', 'Yonex', 'Túi cầu lông Yonex VA BA02631V là mẫu Expert Tournament Bag VA thuộc bộ sưu tập Viktor Axelsen của Yonex. Đây là dòng túi ngang dành cho người chơi cần mang nhiều vợt, giày, quần áo tập, ống cầu và phụ kiện trong cùng một chuyến đi sân hoặc ngày thi đấu.\nVới kích thước 76 × 19 × 33 cm, túi Yonex VA BA02631V có form dài đặc trưng của túi vợt tournament, hỗ trợ sắp xếp đồ dùng tách biệt thay vì dồn chung vào một ngăn. Phối màu xanh đậm cùng chi tiết VA và điểm nhấn vàng tạo nên diện mạo thể thao, đồng bộ với các sản phẩm trong VA Collection.\nTúi cầu lông Yonex VA BA02631V là gì?\nTúi cầu lông Yonex VA BA02631V là túi vợt ngang thuộc dòng Expert Tournament Bag của Yonex. Sản phẩm có khoang chứa...', 3150000, 'p-29-tui-cau-long-yonex-va-ba02631v-chinh-hang.webp'),
    (44, 3, 'Áo Yonex Essential 5 RM-S092-3580-ESST5-S', 'Yonex', 'Áo Yonex Essential 5 RM-S092-3580-ESST5-S là mẫu áo thun cổ tròn nam có thiết kế thể thao gọn gàng, phù hợp để chơi cầu lông, tập luyện và mặc hằng ngày. Sản phẩm thuộc dòng Essentia 5 của Yonex, mang đến lựa chọn trang phục dễ phối cho người chơi yêu thích phong cách năng động.\nMẫu áo hiện có hai phiên bản màu Orchid Tint và Marina, cùng dải size từ S đến 2XL để người mặc dễ lựa chọn theo vóc dáng và nhu cầu vận động.\nThông số áo Yonex Essential 5 RM-S092-3580-ESST5-S\nThông tin\nChi tiết\nThương hiệu\nYonex\nTên sản phẩm\nYonex Essential 5\nMã sản phẩm\nRM-S092-3580-ESST5-S\nKiểu dáng\nÁo thun cổ tròn nam\nMàu sắc\nOrchid Tint, Marina\nKích thước\nS, M, L, XL, 2XL\nPhù hợp\nChơi cầu lông, tập luyện, mặc...', 249000, 'p-26-ao-yonex-essential-5-rm-s092-3580-esst5-s.webp'),
    (45, 2, 'Giày Cầu Lông Yonex SHB 65Z Anv White Gold Chính Hãng', 'Yonex', 'Giày Cầu Lông Yonex SHB 65Z Anv White Gold Chính Hãng chính hãng thương hiệu Yonex. Nguồn thông số tham khảo từ Vợt Cầu Lông Shop.', 4200000, 'p-14-giay-cau-long-yonex-shb-65z-anv-white-gold.webp'),
    (46, 1, 'Vợt Cầu Lông Yonex Astrox 88d Tour 2024 Chính Hãng', 'Yonex', 'Giới thiệu sản phẩm\nYonex Astrox 88D Tour 2024 chính hãng là phiên bản nâng cấp thuộc dòng Astrox nổi tiếng của Yonex, được thiết kế dành cho người chơi yêu thích lối đánh tấn công mạnh mẽ từ cuối sân. Cây vợt sở hữu công nghệ Rotational Generator System giúp tối ưu khả năng phân bổ trọng lượng, mang lại cảm giác vung vợt ổn định và liên kết tốt giữa các pha cầu.\nPhiên bản 2024 được cải tiến về độ ổn định khung và khả năng truyền lực, hỗ trợ người chơi tạo ra những cú smash cắm và uy lực hơn. Đây là lựa chọn nổi bật trong phân khúc vợt cầu lông Yonex dành cho người chơi công mạnh và kiểm soát tốt nhịp độ trận đấu.\nThông số kỹ thuật\nThương hiệu: Yonex\nDòng sản phẩm: Astrox Series\nTrọng...', 2359200, 'p-04-vot-cau-long-yonex-astrox-88d-tour-2024-ch.webp');
